function prepare(){
 state.practiceFinished=false;state.repeating=false;state.lesson=null;state.feedback=null;state.solved=false;state.revealed=false;state.draft='';state.assembled=[];state.bank=[];state.marks=[];state.zero=false;state.choices=[];state.plan=[];state.turn=0;state.chat=[];state.dialogDone=false;resetVoice();const t=current();if(!t)return;
 state.marks=Array.from({length:state.view==='syntax'?t.words.length:t.word?.length||0},()=> '');state.brush=state.view==='syntax'?(ROLES[state.topic]?state.topic:'subject'):state.view==='morphology'&&['prefix','suffix'].includes(state.topic)?state.topic:'root';
 if(state.view==='spelling'){const pool=K.spellingPool(t);state.bank=K.shuffled(pool,K.hash(t.id)+state.nonce).map((text,id)=>({id,text}));}
 if(state.view==='builder')state.bank=K.shuffled(t.chunks.map((_,i)=>i),K.hash(t.id)+state.nonce);
 if(state.view==='dialogues')state.chat=[{who:'coach',text:t.intro},{who:'coach',text:t.turns[0].prompt}];
 ensureLesson();
}
function go(view){rememberSession();rememberCourse();resetVoice();if(META[view])continueSection(view);else{state.view=view;state.review=false;state.reviewLists={};state.category='all';state.topic='all';prepare();}render();window.scrollTo({top:0,behavior:'smooth'});}
function complete(){if(!state.revealed){progress.done[key()]=true;progress.completions[completionKey()]=true;delete progress.mistakes[key()];if(inSpellingCourse())progress.spellingCourse.done[state.grade+':'+state.mode.spelling+':'+current().id]=true;save();}state.solved=true;}
function mistake(){progress.mistakes[key()]=true;save();}
function progressBar(n,total){return `<div class="progress-track"><i style="width:${total?Math.min(100,n/total*100):0}%"></i></div>`;}
function shell(content){return `<div class="app-shell"><aside class="sidebar"><a href="#" class="brand" data-action="home"><span class="brand-icon">${ico('book')}</span><span><span class="brand-name">словоград<span>·</span></span><span class="brand-sub">Русский с интересом</span></span></a><div class="side-label">МАЛЕНЬКИЕ ОТКРЫТИЯ</div><nav aria-label="Разделы тренажёра"><button class="nav-btn ${state.view==='home'?'active':''}" data-view="home">${ico('home')}<span>Мой Словоград</span></button>${Object.entries(META).map(([id,m])=>`<button class="nav-btn ${state.view===id?'active':''}" data-view="${id}" aria-label="${m.title}"><span class="nav-icon ${m.color}">${ico(m.icon)}</span><span>${m.title}</span></button>`).join('')}<button class="nav-btn ${state.view==='progress'?'active':''}" data-view="progress" aria-label="Мои открытия">${ico('chart')}<span>Мои открытия</span></button></nav><div class="sidebar-bottom"><div class="sidebar-coach">${window.RUS_ART.owl}<p>Ошибка — это подсказка.<br><b>Попробуем ещё раз!</b></p></div><div class="mini-progress"><span>Твои открытия <strong>${countAll()}</strong></span>${progressBar(countAll(),Object.values(META).reduce((n,m)=>n+(D[m.data]?.length||0),0)+(D.prepositions?.length||0))}</div></div></aside><main class="main"><header class="topbar"><div class="topbar-location"><a class="hub-link" href="../" aria-label="Все игры — главная страница">${ico('back')}<span>Все игры</span></a><div class="breadcrumb">Русский язык <span>/</span> <strong>${META[state.view]?.title|| (state.view==='progress'?'Мои открытия':'Мой Словоград')}</strong></div></div><div class="top-actions"><label class="grade-select"><span class="sr-only">Класс</span><select data-control="grade"><option value="1" ${state.grade===1?'selected':''}>1 класс</option><option value="2" ${state.grade===2?'selected':''}>2 класс</option></select></label><button class="icon-btn sound-toggle ${state.sound?'on':''}" data-action="sound" aria-label="${state.sound?'Выключить':'Включить'} озвучку" aria-pressed="${state.sound}">${ico('sound')}</button><button class="icon-btn" data-action="help" aria-label="Как заниматься">${ico('help')}</button></div></header>${content}<footer class="app-footer"><span>Словоград · учимся в своём темпе</span><span>1–2 класс · слова, мысли и маленькие открытия</span></footer></main></div>`;}
function intro(eyebrow,title,text){return `<div class="intro"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${text}</p></div>`;}
function home(){const total=Object.values(META).reduce((n,m)=>n+availableCount(m.data),0)+availableCount('prepositions');return resumeHome()+`<section class="hero"><div class="hero-copy"><span class="hero-badge">${ico('star')} МЕСТО, ГДЕ СЛОВА ОЖИВАЮТ</span><h1>Большой мир<br><span>маленьких слов</span></h1><p>Привет! Я сова Соня. Давай строить слова, сочинять истории и открывать секреты русского языка.</p><div class="hero-actions"><button class="btn primary" data-view="spelling">Начать приключение ${ico('arrow')}</button><button class="btn ghost" data-action="greeting">${ico('sound')} Послушать Соню</button></div><div class="hero-note">Без оценок и спешки. Каждая попытка помогает учиться.</div></div><div class="hero-art" aria-hidden="true">${window.RUS_ART.hero}</div></section><div class="section-heading"><div><div class="eyebrow">ВЫБИРАЙ, ЧТО ИНТЕРЕСНО</div><h2>Шесть мест для открытий</h2></div><span class="muted">${total} заданий для ${state.grade}-го класса</span></div><div class="section-grid">${Object.entries(META).map(([id,m],i)=>`<button class="section-card ${m.color}" data-view="${id}"><span class="section-icon">${ico(m.icon)}</span><span class="section-number">0${i+1}</span><h3>${m.title}</h3><p>${m.desc}</p><div class="section-card-bottom"><span>${id==='morphology'?availableCount('morphology')+' слов + '+availableCount('prepositions')+' задания':availableCount(m.data)+' заданий'}</span>${ico('arrow')}</div></button>`).join('')}</div><div class="dashboard-lower"><section class="daily-card"><span class="eyebrow">ПОНЕМНОГУ КАЖДЫЙ ДЕНЬ</span><h3>Маленькая прогулка — большие открытия</h3><p>Собери слово, придумай предложение и расскажи Соне что-нибудь интересное. Можно заниматься 10–15 минут.</p><div class="chip-row"><span class="chip">${ico('letters')} Собрать</span><span class="chip">${ico('bulb')} Понять</span><span class="chip">${ico('mic')} Рассказать</span></div></section><section class="coach-card"><span class="eyebrow">УЖЕ ПОЛУЧИЛОСЬ</span><div class="stats-row"><div class="stat"><strong>${countAll()}</strong><span>открытий</span></div><div class="stat"><strong>${Object.keys(progress.mistakes).length}</strong><span>для повторения</span></div></div><button class="btn secondary" data-view="progress">Посмотреть успехи ${ico('arrow')}</button></section></div>`;}
function guidance(){const t=current(),section=state.view;let title='',text='',extra='';if(section==='spelling'){title=t.category;text=t.rule;extra=`${t.checkWord?`<div class="question-card">Проверочное слово: <b>${esc(t.checkWord)}</b></div>`:''}<p>Сначала попробуй сам. Можно собрать слово, написать его или устроить маленький диктант.</p>`;}else if(section==='morphology'&&state.mode.morphology==='prepositions'){title='Предлог или приставка?';text='Предлог — отдельное слово: на столе. Приставка — часть слова: написал.';extra='<div class="question-card">На <b>большом</b> столе: между предлогом и словом можно вставить другое слово.</div><p>Предлог не входит в состав слова.</p>';}else if(section==='morphology'){title='У каждого слова есть секрет';text='Родственные слова похожи по смыслу и имеют общий корень. Окончание меняется вместе со словом.';extra=`<div class="legend">${Object.entries(PARTS).map(([id,x])=>`<div class="legend-item"><i class="swatch ${id}" style="background:${x.color}"></i><span><b>${x.name}</b><small>${x.question}</small></span></div>`).join('')}</div><p>Основа — слово без окончания. ∅ обозначает нулевое окончание.</p><div class="question-card">Родственные слова: <b>${esc(t.relatives.join(', '))}</b></div>`;}else if(section==='syntax'){title='Главные в предложении';text='Подлежащее называет, о ком или о чём говорится. Сказуемое сообщает действие.';extra=`<div class="legend">${Object.entries(ROLES).filter(([id])=>state.mode.syntax==='full'||['subject','predicate'].includes(id)).map(([id,x])=>`<div class="legend-item"><i class="swatch" style="background:${x.color}"></i><span><b>${x.name}</b><small>${x.question}</small></span></div>`).join('')}</div><p>Предлог сам не бывает членом предложения. В полном разборе выделяем всю группу: например, «на ветке».</p>`;}else if(section==='builder'){title='Мысли любят порядок';text='У предложения есть смысл. Первое слово начинается с большой буквы, а в конце стоит знак.';extra='<div class="question-card">Сегодня собираем по заданной модели. В обычной речи порядок слов может быть разным.</div><p>Перетаскивай карточки или нажимай на них. Карточку в предложении можно вернуть обратно нажатием.</p>';}else if(section==='creative'){title='Красиво — значит точно';text='Не нужно много сложных слов. Выбери такие слова, которые помогают представить картину.';extra=`<ol class="guide-plan">${t.plan.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>${esc(t.tips[0]||'Прочитай вслух: звучит ли твоя мысль понятно?')}</p>`;}else{title='Соня умеет слушать';text='Это учебный диалог по шагам. Соня задаёт вопросы, а ты придумываешь свои ответы.';extra='<p>Можно говорить или писать. После распознавания проверь текст — устройство иногда ошибается.</p><div class="question-card">Не нужно называть фамилию, адрес или школу. Рассказываем об идеях и выдуманных героях.</div>';}return `<aside class="guide-panel"><section class="guide-card"><span class="guide-icon">${ico('bulb')}</span><div class="eyebrow">МАЛЕНЬКАЯ ПОДСКАЗКА</div><h3>${title}</h3><p>${esc(text)}</p>${extra}${inlineLesson()}${(section==='morphology'&&state.mode.morphology==='parts'&&PARTS[state.brush])||(section==='syntax'&&ROLES[state.brush])?`<div class="question-card active-part-rule"><b>${esc((section==='morphology'?PARTS:ROLES)[state.brush].name)}</b><p>${esc((section==='morphology'?PARTS:ROLES)[state.brush].description)}</p></div>`:''}<button class="btn ghost" data-action="read-rule">${ico('sound')} Послушать объяснение</button></section><section class="guide-card sonya-tip">${window.RUS_ART.owl}<p>Не торопись. Можно ошибиться, подумать и попробовать ещё!</p></section></aside>`;}
function exercise(){if(inSpellingCourse()&&state.courseFinished)return courseEnd();if(!inSpellingCourse()&&state.practiceFinished)return practiceEnd();const m=META[state.view],t=current(),a=list();if(t&&ensureLesson())return lessonScreen();if(!t)return intro('МОЖНО ВЫДОХНУТЬ','Всё повторено!','В этом наборе пока нет заданий для повторения.')+tabs()+`<button class="btn primary" data-action="all-tasks">Открыть все задания ${ico('arrow')}</button>`;const categorySelect=state.view==='spelling'?`<label class="select-field">Тема<select data-control="category"><option value="all">Все темы</option>${spellingCategories().map(c=>`<option ${c===state.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`:'';return intro('ОДНА МАЛЕНЬКАЯ ПОБЕДА ЗА ДРУГОЙ',m.title,m.desc)+`<div class="learning-layout"><section class="exercise-card ${m.color}"><div class="exercise-head"><span class="section-tag">${ico(m.icon)} ${state.grade} КЛАСС ${state.review?'· ПОВТОРЯЕМ':''}</span>${t.level>state.grade?'<span class="difficulty-badge">Шаг сложнее</span>':state.grade===2&&t.level===1?'<span class="difficulty-badge">Повторение основ</span>':''}<span class="task-index">${(state.index[source()]||0)%a.length+1} / ${a.length}</span></div>${gradeContext()}<div class="task-toolbar">${categorySelect}${topicOptions().length?`<label class="select-field topic-picker">Тема<select data-control="topic" aria-label="Выбрать учебную тему">${topicOptions().map(option=>`<option value="${option.id}" ${state.topic===option.id?'selected':''}>${esc(option.label)}</option>`).join('')}</select></label>`:''}<label class="select-field exercise-picker">Задание<select data-control="exercise" aria-label="Выбрать задание">${a.map((item,i)=>`<option value="${i}" ${i===(state.index[source()]||0)%a.length?'selected':''}>${taskMark(item)}${i+1}. ${esc(state.view==='spelling'&&state.mode.spelling==='dictation'?'Слово под диктовку · '+item.category:taskLabel(item))}</option>`).join('')}</select></label><button class="btn ghost" data-action="random-task">Случайное</button><button class="btn ghost" data-action="read-task">${ico('sound')} Послушать задание</button></div>${tabs()}${taskProgress()}<div class="task-body">${state.view==='spelling'?spellingJourney():''}${learningStages(false)}${topicRule()}${state.view==='spelling'?spellingView():state.view==='morphology'?morphologyView():state.view==='syntax'?syntaxView():state.view==='builder'?builderView():state.view==='creative'?creativeView():dialogView()}${feedbackView()}${state.view!=='dialogues'?`<div class="action-row task-actions"><button class="btn ghost" data-action="hint">${ico('bulb')} Подсказка</button><button class="btn secondary" data-action="reset-task">${ico('reset')} Заново</button><button class="btn primary" data-action="${state.solved?'next':'check'}">${state.solved?'Следующее задание':'Проверить'} ${ico(state.solved?'arrow':'check')}</button></div>`:''}</div><div class="task-nav"><button class="btn ghost" data-action="prev">${ico('back')} Назад</button><span>${taskCompleted(t)?'✓ Этот шаг уже получился!':'Учимся в своём темпе'}</span><button class="btn ghost" data-action="next">Дальше ${ico('arrow')}</button></div></section>${guidance()}</div>`;}
function tabs(){if(inSpellingCourse())return '';let pairs=state.view==='spelling'?[['construct','Собери'],['write','Напиши'],['dictation','Диктант']]:state.view==='morphology'?[['parts','Части слова'],['prepositions','Предлог и приставка']]:state.view==='syntax'?[['base','Главные слова'],['full','Весь разбор · сложнее']]:[];return pairs.length?`<div class="mode-tabs" role="tablist">${pairs.map(([id,label])=>`<button class="${state.mode[state.view]===id?'active':''}" role="tab" aria-selected="${state.mode[state.view]===id}" data-mode="${id}">${label}</button>`).join('')}</div>`:'';}
function spellingView(){const t=current(),mode=state.mode.spelling;return `<h2>${mode==='construct'?'Собери слово по буквам':mode==='write'?'Впиши слово целиком':'Слушай и пиши'}</h2><p class="task-subtitle">${mode==='construct'?'Нажимай на буквы или перетаскивай их. В наборе есть лишние: вспомни правило и выбери верные.':mode==='write'?'Подумай о пропущенной букве. Напиши слово самостоятельно.':'Послушай слово, затем напиши его. Можно прослушать ещё раз.'}</p>${mode==='dictation'&&!state.solved?`<button class="dictation-button" data-action="say-word">${ico('sound')} Послушать слово</button>`:`<div class="big-word">${[...(state.solved?t.word:t.masked)].map(c=>`<span class="letter ${c==='□'?'gap':''}">${c}</span>`).join('')}</div>`}${mode==='construct'?`<div class="word-slots drop-area" data-drop="word" role="group" aria-label="Собираем слово">${Array.from({length:t.word.length},(_,i)=>state.assembled[i]!==undefined?`<button class="slot filled" data-remove="${i}" data-drag="assembled" data-id="${state.assembled[i]}" data-slot="${i}" aria-label="Убрать букву ${state.bank[state.assembled[i]].text}">${state.bank[state.assembled[i]].text}</button>`:`<span class="slot empty" data-slot="${i}">${i+1}</span>`).join('')}</div><div class="letter-bank drop-area" data-drop="bank" aria-label="Буквы для сборки">${state.bank.map(x=>`<button class="letter-tile ${state.assembled.includes(x.id)?'used':''}" data-letter="${x.id}" data-drag="letter" data-id="${x.id}" ${state.assembled.includes(x.id)||state.solved?'disabled':''}>${x.text}</button>`).join('')}</div>`:`<label class="answer-label" for="word-answer">Моё слово<input id="word-answer" class="writing-input answer-input" data-input="draft" value="${esc(state.draft)}" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" placeholder="Пиши здесь…" ${state.solved?'disabled':''}></label>`}${state.solved?`<div class="example-card"><b>${esc(t.word)}</b><p>${esc(t.explain)}</p><p>${esc(t.sentence)}</p></div>`:''}`;}
function brushes(defs){return `<div class="brushes" role="group" aria-label="Выбери цвет для разбора">${Object.entries(defs).map(([id,x])=>`<button class="brush ${state.brush===id?'active':''} ${id}" data-brush="${id}" aria-pressed="${state.brush===id}"><i style="background:${x.color}"></i>${x.name}</button>`).join('')}<button class="brush ${state.brush===''?'active':''}" data-brush="" aria-label="Ластик">Ластик</button></div>`;}
function morphologyView(){const t=current();if(state.mode.morphology==='prepositions')return `<h2>Раздельно или слитно?</h2><p class="task-subtitle">Предлог — отдельное слово. Приставка пишется со словом.</p><div class="question-card sentence-context">${esc(t.context)}</div><div class="preposition-pair"><span>${esc(t.left)}</span><span>?</span><span>${esc(t.right)}</span></div><div class="choice-group"><button class="choice-btn ${state.choices[0]==='separate'?'active':''}" data-preposition="separate">${esc(t.left)} ${esc(t.right)}<small>раздельно</small></button><button class="choice-btn ${state.choices[0]==='together'?'active':''}" data-preposition="together">${esc(t.left+t.right)}<small>слитно</small></button></div>${state.solved?`<div class="example-card">${esc(t.explain)}</div>`:''}`;return `<h2>Найди части слова</h2><p class="task-subtitle">${state.topic==='prefix'?'Начни с приставки, затем выдели остальные части слова.':state.topic==='suffix'?'Начни с суффикса, затем выдели остальные части слова.':'Выбери часть слова, затем нажми на её буквы.'} Ластик снимает цвет.</p>${brushes(PARTS)}<div class="morpheme-word" role="group" aria-label="Разбери слово ${esc(t.word)}">${[...t.word].map((c,i)=>`<button class="char ${state.marks[i]||''}" data-mark="${i}" aria-label="Буква ${c}${state.marks[i]?', '+PARTS[state.marks[i]].name:''}" ${state.solved?'disabled':''}>${c}</button>`).join('')}</div><button class="zero-ending ${state.zero?'active':''}" data-action="zero" aria-pressed="${state.zero}">∅ Нулевое окончание</button><p class="muted task-note">Если окончание есть, выдели его буквы. Если оно нулевое — выбери ∅.</p>${state.solved||state.revealed?`<div class="word-base">Основа: <b>${esc(t.base)}</b></div><div class="example-card">${esc(t.explain)}</div>`:''}<button class="btn ghost reveal-button" data-action="reveal">Показать учебный разбор</button>`;}
function syntaxView(){const t=current(),full=state.mode.syntax==='full',defs=Object.entries(ROLES).filter(([id])=>full||['subject','predicate'].includes(id)).reduce((defs,[id,role])=>{defs[id]=role;return defs;},{});return `<h2>${full?'У каждого слова своя работа':'Найди главных героев'}</h2><p class="task-subtitle">${full?'Выбери роль, затем выдели слово или всю группу с предлогом.':'Выдели подлежащее и сказуемое. Остальные слова оставь без цвета.'}</p>${brushes(defs)}<div class="syntax-sentence">${t.words.map((w,i)=>`<button class="syntax-token ${state.marks[i]||''}" data-mark="${i}" ${state.solved?'disabled':''}>${esc(w)}</button>`).join('')}<span class="sentence-punct">${esc(t.punct)}</span></div><div class="question-card"><b>Задавай вопросы</b><p>${esc(t.questions.subject)}<br>${esc(t.questions.predicate)}</p></div>${state.solved||state.revealed?`<div class="example-card">${esc(t.explain)}</div>`:''}<button class="btn ghost reveal-button" data-action="reveal">Показать учебный разбор</button>`;}
function builderView(){const t=current();return `<h2>Построй предложение</h2><p class="task-subtitle">Сегодня строим по этой модели. Нажимай на карточки или перетаскивай их.</p><div class="pattern">${esc(t.pattern)}</div><div class="sentence-slots drop-area" data-drop="sentence"><span class="sr-only">Твоё предложение</span>${state.assembled.length?state.assembled.map((id,i)=>`<button class="sentence-chip ${t.chunks[id].role}" data-remove="${i}" data-drag="assembled" data-id="${id}" data-slot="${i}">${esc(t.chunks[id].text)}</button>`).join(''):'<span class="empty-message">Положи сюда первую карточку</span>'}</div><div class="builder-bank drop-area" data-drop="bank">${state.bank.filter(id=>!state.assembled.includes(id)).map(id=>`<button class="sentence-chip ${t.chunks[id].role}" data-chunk="${id}" data-drag="chunk" data-id="${id}"><small>${ROLES[t.chunks[id].role].question}</small>${esc(t.chunks[id].text)}</button>`).join('')}</div>${state.solved?`<div class="example-card"><b>${esc(K.sentence(t.chunks,state.assembled))}</b><p>${esc(t.explain)}</p><button class="btn ghost" data-action="say-built">${ico('sound')} Послушать</button></div>`:''}`;}
function voicePanel(){const caps=V.capabilities();return `<section class="voice-panel"><div class="voice-panel-heading"><span>${ico('mic')} Можно ответить голосом</span><small>Микрофон включается только по кнопке</small></div><div class="voice-actions">${caps.recognition?`<button class="btn secondary ${state.voice.listening?'recording':''}" data-action="${state.voice.listening?'stop-listening':'listen'}">${ico(state.voice.listening?'stop':'mic')} ${state.voice.listening?'Остановить':'Сказать ответ'}</button>`:`<span class="voice-unsupported">Распознавание в этом браузере недоступно. Можно использовать диктовку клавиатуры.</span>`}${caps.recording?`<button class="btn ghost ${state.voice.recording?'recording':''}" data-action="${state.voice.recording?'stop-recording':'record'}">${ico(state.voice.recording?'stop':'mic')} ${state.voice.recording?'Остановить запись':'Записать и послушать себя'}</button>`:''}</div><div class="voice-status" role="status">${esc(state.voice.status||'Можно говорить, а можно написать — выбирай сам.')}</div>${state.voice.url?`<audio controls src="${esc(state.voice.url)}" aria-label="Послушать свою запись"></audio>`:''}<p class="voice-footnote">Запись остаётся на устройстве. Для распознавания браузер может использовать свою сетевую службу. Не оцениваем произношение по расшифровке.</p></section>`;}
function creativeView(){const t=current();return `<h2>${esc(t.prompt)}</h2><div class="creative-seed"><small>БЫЛО ПРОСТОЕ ПРЕДЛОЖЕНИЕ</small><strong>${esc(t.seed)}</strong></div><p class="task-subtitle">Выбери слова-помощники или напиши свой вариант. Можно сказать его вслух.</p>${t.banks.map((bank,i)=>`<div class="choice-group"><h3>${esc(bank.label)}</h3>${bank.options.map((word,j)=>`<button class="choice-btn ${state.choices[i]===j?'active':''}" data-choice="${i}:${j}">${esc(word)}</button>`).join('')}</div>`).join('')}<button class="btn secondary" data-action="assemble-creative">Собрать мой вариант ${ico('magic')}</button><label class="answer-label" for="creative-answer">Моё предложение<textarea id="creative-answer" class="writing-input" data-input="draft" rows="3" placeholder="Моя мысль…">${esc(state.draft)}</textarea></label>${voicePanel()}<div class="plan-check"><h3>Проверяю себя по плану</h3><ul class="checklist">${t.plan.map((x,i)=>`<li class="${state.plan[i]?'done':''}"><label><input type="checkbox" data-plan="${i}" ${state.plan[i]?'checked':''}>${esc(x)}</label></li>`).join('')}</ul><p class="task-note muted">У красивой речи много вариантов. Автопроверка смотрит только на заглавную букву, знак в конце и повтор слова. Смысл проверяем по плану.</p></div>${state.solved?`<div class="example-card"><small>ЕЩЁ ОДИН ВАРИАНТ</small><p>${esc(t.example)}</p><button class="btn ghost" data-action="say-draft">${ico('sound')} Прочитать моё предложение · голос устройства</button></div>`:''}`;}
function dialogView(){const t=current(),turn=t.turns[state.turn];return `<h2>${esc(t.title)}</h2><p class="task-subtitle">Учебный диалог по шагам · ${t.turns.length} вопроса</p><div class="dialog-chat" aria-live="polite">${state.chat.map(x=>`<div class="chat-message ${x.who}">${x.who==='coach'?`<span class="chat-avatar">${window.RUS_ART.owl}</span>`:''}<div><small>${x.who==='coach'?'Соня':'Твой ответ'}</small><p>${esc(x.text)}</p></div></div>`).join('')}</div>${state.dialogDone?`<div class="example-card"><b>Твой рассказ готов!</b><p>${esc(t.wrap)}</p><button class="btn secondary" data-action="say-story">${ico('sound')} Послушать мои ответы · голос устройства</button></div><div class="action-row"><button class="btn primary" data-action="next">Новый разговор ${ico('arrow')}</button><button class="btn ghost" data-action="reset-task">Поговорить ещё раз</button></div>`:`<div class="dialog-form"><span class="step-caption">Вопрос ${state.turn+1} из ${t.turns.length}</span><label class="answer-label" for="dialog-answer">${esc(turn.prompt)}<textarea id="dialog-answer" class="writing-input" data-input="draft" rows="3" placeholder="Я думаю…">${esc(state.draft)}</textarea></label><div class="dialog-hint">${ico('bulb')} ${esc(turn.hint)}</div>${voicePanel()}<div class="action-row"><button class="btn ghost" data-action="read-task">${ico('sound')} Повторить вопрос</button><button class="btn primary" data-action="dialog-send">Ответить Соне ${ico('arrow')}</button></div></div>`}`;}
function feedbackView(){return state.feedback?`<div class="feedback ${state.feedback.type}" role="status">${ico(state.feedback.type==='success'?'check':'bulb')}<div>${esc(state.feedback.text)}</div></div>`:'';}
function progressView(){return intro('ПОЛУЧАЕТСЯ ВСЁ БОЛЬШЕ','Мои открытия','Здесь хранятся твои маленькие победы. Можно вернуться к тому, что хочется закрепить.')+`<div class="stats-row progress-stats"><div class="stat"><strong>${countAll()}</strong><span>заданий получилось</span></div><div class="stat"><strong>${Object.keys(progress.mistakes).length}</strong><span>нуждаются в повторении</span></div><div class="stat"><strong>${progress.creations.length}</strong><span>маленьких творений</span></div></div><div class="progress-grid">${Object.entries(META).map(([id,m])=>{const n=doneCount(m.data)+(id==='morphology'?doneCount('prepositions'):0),total=D[m.data].length+(id==='morphology'?D.prepositions.length:0);return `<section class="progress-module ${m.color}"><span class="section-icon">${ico(m.icon)}</span><h3>${m.title}</h3><p>${n} / ${total} открытий</p>${progressBar(n,total)}<div class="action-row"><button class="btn secondary" data-view="${id}">Продолжить</button><button class="btn ghost" data-review="${id}">Повторить</button></div></section>`;}).join('')}</div>${progress.creations.length?`<section class="creations"><h2>Мои предложения</h2>${progress.creations.slice(-6).reverse().map(x=>`<blockquote>${esc(x.text)}</blockquote>`).join('')}</section>`:''}<p class="storage-note muted">${memory?'Хранилище недоступно: прогресс сохранится только до закрытия страницы.':'Прогресс и творения хранятся в этом браузере на этом устройстве.'}</p><button class="btn ghost" data-action="reset-progress">Начать заново</button>`;}
function render(){const focused=document.activeElement?.id;const openRules=$$('details[data-rule-key][open]').map(el=>el.dataset.ruleKey);$('#app').innerHTML=shell(state.view==='home'?home():state.view==='progress'?progressView():exercise());openRules.forEach(key=>{const el=$(`[data-rule-key="${key}"]`);if(el)el.open=true;});if(focused&&$('#'+focused))$('#'+focused).focus({preventScroll:true});rememberSession();}
function check(){
 if(ensureLesson()){render();return;}if(state.solved)return;if(state.voice.recording||state.voice.listening)resetVoice();const t=current();if(!t)return;let ok=false,success='';
 if(state.view==='spelling'){
  const answer=state.mode.spelling==='construct'?state.assembled.map(id=>state.bank[id].text).join(''):state.draft;
  if(!answer.trim()){notify('Сначала собери или напиши слово. Можно послушать его.');render();return;}
  ok=K.spelling(t,answer);success=`Получилось: ${t.word}! ${t.explain}`;
  if(!ok){mistake();notify(K.spellingFeedback(t,answer),'error');}
 }else if(state.view==='morphology'&&state.mode.morphology==='prepositions'){
  if(!state.choices[0]){notify('Выбери: написать слитно или раздельно.');render();return;}
  ok=(state.choices[0]==='together')===t.together;success=t.explain;
  if(!ok){mistake();notify('Подумай ещё: это отдельное слово-предлог или часть слова-приставка?','error');}
 }else if(state.view==='morphology'){
  ok=K.morphology(t,state.marks,state.zero);success=t.explain;
  if(!ok){mistake();const expected=K.morphemes(t),i=expected.findIndex((x,i)=>state.marks[i]!==x);notify(i>=0?`Посмотри на букву «${t.word[i]}» на месте ${i+1}. Подбери родственные слова и проверь её часть.`:'Буквы выделены верно. Проверь, есть ли у этого слова нулевое окончание.','error');}
 }else if(state.view==='syntax'){
  ok=K.syntax(t,state.marks,state.mode.syntax==='full');success=t.explain;
  if(!ok){mistake();notify('Задай вопросы: о ком или о чём говорится? Что этот герой делает? Выдели нужные слова и попробуй ещё.','error');}
 }else if(state.view==='builder'){
  ok=K.builder(t,state.assembled);success=t.explain;
  if(!ok){mistake();notify(state.assembled.length!==t.chunks.length?'Добавь все карточки, чтобы мысль получилась полной.':'Попробуй порядок по модели сверху. В обычной речи возможны другие варианты, но сейчас тренируем именно эту модель.','hint');}
 }else if(state.view==='creative'){
  const checks=K.writingChecks(state.draft),failed=checks.filter(x=>!x.ok);
  if(failed.length){notify('Проверим оформление: '+failed.map(x=>x.text.toLocaleLowerCase('ru')).join('; ')+'. Это проверка по простым признакам, а не оценка всей грамматики.','hint');requireLesson('writing');render();return;}
  if(!t.plan.every((_,i)=>state.plan[i])){notify('Прочитай свой вариант и отметь пункты плана, которые ты выполнил.');render();return;}
  ok=true;success='Твоё предложение сохранено! Прочитай его вслух: все ли слова помогают представить картину?';
  const previous=progress.creations.find(x=>x.id===t.id&&x.text===state.draft.trim());if(!previous){progress.creations.push({id:t.id,text:state.draft.trim().slice(0,1500)});progress.creations=progress.creations.slice(-30);}
 }
 if(!ok)requireLesson(remediationLesson());
 if(ok){complete();notify(state.revealed?'Это учебный разбор. Теперь попробуй следующее задание самостоятельно.':success,'success');if(!state.revealed)celebrate();}
 render();
}
function next(delta=1){
 if(ensureLesson()){render();return;}
 if(inSpellingCourse()){nextCourse(delta);return;}
 const a=list(),data=source(),oldIndex=state.index[data]||0;
 if(state.review&&delta>0&&!a.some(t=>progress.mistakes[data+':'+t.id])){state.reviewLists[data]=[];state.index[data]=0;prepare();render();return;}
 let nextIndex=(oldIndex+delta+a.length)%Math.max(1,a.length),repeating=state.repeating;
 if(!state.review&&delta>0&&!repeating){nextIndex=-1;for(let step=1;step<=a.length;step++){const i=(oldIndex+step)%a.length;if(!taskCompleted(a[i])){nextIndex=i;break;}}if(nextIndex<0){state.practiceFinished=true;state.solved=false;state.lesson=null;render();return;}}
 if(repeating&&delta>0&&oldIndex===a.length-1){state.practiceFinished=true;state.repeating=false;render();return;}
 if(state.review&&delta>0){for(let step=1;step<=a.length;step++){const i=(oldIndex+step)%a.length;if(progress.mistakes[data+':'+a[i].id]){nextIndex=i;break;}}}
 state.index[data]=nextIndex;state.nonce++;prepare();state.repeating=repeating||delta<0&&taskCompleted(current());render();$('.exercise-card')?.scrollIntoView({behavior:'smooth',block:'start'});
}
function nextCourse(delta=1){
 const unit=courseUnit(),stage=unit?.stages.find(stage=>stage.mode===state.mode.spelling);if(!unit||!stage||state.courseFinished)return;
 const a=stage.tasks,old=(state.index.spelling||0)%a.length;
 if(delta<0){state.index.spelling=(old-1+a.length)%a.length;rememberCourse();prepare();render();return;}
 if(!courseDone(stage.mode,a[old])){notify('Сначала реши и проверь это слово. К следующему этапу перейдём, когда все слова здесь получатся.');render();return;}
 if(!stageDone(stage)){for(let step=1;step<=a.length;step++){const i=(old+step)%a.length;if(!courseDone(stage.mode,a[i])){state.index.spelling=i;break;}}rememberCourse();}
 else{const nextStage=unit.stages.slice(unit.stages.indexOf(stage)+1).find(stage=>!stageDone(stage));if(nextStage)selectCourseStage(unit,nextStage,nextStage.tasks.findIndex(task=>!courseDone(nextStage.mode,task)));else if(state.category==='all')resumeCourse();else state.courseFinished=true;}
 state.nonce++;prepare();render();$('.exercise-card,.course-end')?.scrollIntoView({behavior:'smooth',block:'start'});
}
function spellingCategories(){return [...new Set((inSpellingCourse()?D.spelling.filter(t=>t.level<=state.grade):gradePool('spelling')).map(t=>t.category))];}
function spellingJourney(){
 if(!inSpellingCourse())return `<p class="journey-note">Свободная практика: можно выбрать любой режим. Здесь не закрываются шаги маршрута.${state.review?' Повторяем слова, в которых были ошибки.':''} <button class="btn ghost practice-toggle" data-action="spelling-course">К маршруту по правилам</button></p>`;
 const unit=courseUnit();if(!unit)return '';const done=unit.stages.reduce((n,stage)=>n+stage.tasks.filter(task=>courseDone(stage.mode,task)).length,0),total=unit.stages.reduce((n,stage)=>n+stage.tasks.length,0),labels={construct:'Собери',write:'Напиши',dictation:'Диктант'};
 return `<section class="spelling-journey" aria-label="Закрепление правила"><div class="journey-heading"><b>${esc(unit.category)} · три шага</b><small>${done} / ${total} слов проверено</small></div><div class="journey-stages">${unit.stages.map((stage,i)=>{const complete=stageDone(stage),locked=!unit.stages.slice(0,i).every(stageDone);return `<button class="journey-stage ${state.mode.spelling===stage.mode?'active':''} ${complete?'complete':''}" data-course-mode="${stage.mode}" ${locked?'disabled':''} ${state.mode.spelling===stage.mode?'aria-current="step"':''}><b>${i+1}. ${labels[stage.mode]}</b><span>${stage.tasks.filter(task=>courseDone(stage.mode,task)).length} / ${stage.tasks.length}${complete?' · готово':locked?' · впереди':''}</span></button>`;}).join('')}</div><p class="journey-note">На каждом шаге — другие слова на это правило. Следующее правило откроется после диктанта.</p><button class="btn ghost practice-toggle" data-action="spelling-free">Выбрать режим свободно</button></section>`;
}
function gradeContext(){return `<div class="grade-context"><span>${state.grade===1?'1 класс: короткие слова и первые способы проверки.':'2 класс: более сложные примеры и повторение основ.'}</span>${state.grade===1&&!inSpellingCourse()?`<label><input type="checkbox" data-control="harder" ${state.harder?'checked':''}> Добавить задания 2 класса</label>`:''}</div>`;}
function completedCourseMap(){const units=spellingCourse().filter(unit=>state.category==='all'||unit.category===state.category),labels={construct:'Собрали',write:'Написали',dictation:'Записали под диктовку'};return `<details class="course-history"><summary>Какие слова уже пройдены?</summary>${units.map(unit=>`<section><h3>${esc(unit.category)}</h3>${unit.stages.map(stage=>`<h4>${labels[stage.mode]} · ${stage.tasks.filter(t=>courseDone(stage.mode,t)).length}/${stage.tasks.length}</h4><div class="completed-words">${stage.tasks.map((t,i)=>`<span>${courseDone(stage.mode,t)?'✓ '+esc(t.word):'○ Слово '+(i+1)}</span>`).join('')}</div>`).join('')}</section>`).join('')}</details>`;}
function courseEnd(){const units=spellingCourse(),unit=courseUnit(),nextUnit=units[units.findIndex(item=>item.category===unit?.category)+1];return intro('ПРАВИЛО ЗАКРЕПЛЕНО','Три шага позади!',state.category==='all'?'Все правила этого класса пройдены в трёх режимах. Можно вернуться к трудным словам или повторить маршрут.':`Ты собирал, писал и записывал под диктовку слова на правило «${state.category}».`)+`<section class="exercise-card course-end"><h2>${state.category==='all'?'Маршрут завершён':esc(state.category)+' — получилось!'}</h2><p>Отметки каждого этапа сохранены отдельно. Старые открытия тоже на месте.</p>${completedCourseMap()}<div class="action-row">${nextUnit&&state.category!=='all'?`<button class="btn primary" data-action="next-course-topic">Следующее правило: ${esc(nextUnit.category)} ${ico('arrow')}</button>`:''}<button class="btn secondary" data-action="repeat-course">Повторить слова</button><button class="btn ghost" data-action="spelling-free">Свободная практика</button><button class="btn ghost" data-view="home">На главную</button></div></section>`;}
function chooseCourseMode(mode){
 if(state.lesson)return;const unit=courseUnit(),index=unit?.stages.findIndex(stage=>stage.mode===mode);if(index===undefined||index<0||mode===state.mode.spelling)return;
 if(!unit.stages.slice(0,index).every(stageDone)){notify('Сначала проверим все слова предыдущего шага.');render();return;}
 rememberCourse();selectCourseStage(unit,unit.stages[index]);if(stageDone(unit.stages[index])){prepare();state.repeating=true;}else resumeContext();render();
}
function hint(){const t=current();if(!t)return;const text=state.view==='spelling'?t.hint:state.view==='morphology'?state.mode.morphology==='prepositions'?'Попробуй вставить слово между предлогом и следующим словом: «на большом столе». В приставку другое слово не вставить.':`Вспомни родственные слова: ${t.relatives.join(', ')}. Их общая часть — корень. Меняй форму слова, чтобы найти окончание.`:state.view==='syntax'?`${t.questions.subject} ${t.questions.predicate}`:state.view==='builder'?`Собирай по схеме: ${t.pattern}. Одна карточка может содержать несколько слов.`:state.view==='creative'?t.tips.join(' '):t.turns[state.turn]?.hint;notify(text);render();}
function reveal(){if(ensureLesson()){render();return;}openLesson(lessonForCurrent(),'worked',{after:'reveal'});render();}
function applyWorkedExample(){const t=current();state.revealed=true;if(state.view==='morphology'){state.marks=K.morphemes(t);state.zero=t.parts.some(p=>p.kind==='ending'&&p.text==='');}else{state.marks=t.roles.map(role=>state.mode.syntax==='full'||role==='subject'||role==='predicate'?role:'');}notify('Посмотри на разбор и объяснение. Это учебный пример — отметку за него не ставим.');render();}
function stopSpeaking(){V.stopSpeech();}
function speak(text,force=false,device=false){if(!state.sound&&!force)return;$$('audio').forEach(a=>a.pause());if(state.voice.recording||state.voice.listening){resetVoice();render();}V.speak(text,{device,onError:message=>{notify(message,'hint');render();}});}
function taskSpeech(){const t=current();if(!t)return '';if(state.view==='spelling')return `Слово: ${t.word}. Ещё раз: ${t.word}. Собери или напиши слово самостоятельно.`;if(state.view==='dialogues')return state.dialogDone?t.wrap:t.turns[state.turn].prompt;if(state.view==='morphology')return state.mode.morphology==='prepositions'?`Выбери, как писать: ${t.left}, ${t.right}. Слитно или раздельно?`:`Разбери слово ${t.word} на части. ${state.topic==='prefix'?'Начни с приставки.':state.topic==='suffix'?'Начни с суффикса.':'Сначала найди корень.'} Потом выдели остальные части.`;if(state.view==='syntax'){const goal=topicOptions().find(x=>x.id===state.topic);return `${state.mode.syntax==='full'?'Разбери предложение по членам. '+(goal&&state.topic!=='all'?goal.description:'Сначала найди основу, затем второстепенные члены.'):'Найди подлежащее и сказуемое.'} ${t.words.join(' ')}${t.punct}`;}if(state.view==='builder')return `Собери предложение по модели. ${t.pattern.replace(/→/g,', ')}. Карточки: ${t.chunks.map(x=>x.text).join(', ')}.`;return t.prompt+' '+t.seed;}
function readRule(){const t=current();if(state.view==='syntax'){const goal=topicOptions().find(x=>x.id===state.topic),active=ROLES[state.brush];speak((goal?goal.description+' ':'')+(active?active.description+' ':'')+'Предлог сам по себе не является членом предложения.',true);return;}const text=state.view==='spelling'?t.rule:state.view==='morphology'?state.mode.morphology==='prepositions'?'Предлог — отдельное слово. Приставка — часть слова. Предлог не входит в состав слова.':'Корень — общая часть родственных слов. Приставка стоит перед корнем. Суффикс — после корня. Окончание меняется при изменении формы слова. Основа — слово без окончания.':state.view==='syntax'?'Подлежащее называет, о ком или о чём говорится, и отвечает на вопрос кто или что. Сказуемое обозначает действие и отвечает на вопрос что делает. Предлог отдельно членом предложения не бывает.':state.view==='builder'?'Начинай предложение с большой буквы. В конце поставь точку, вопросительный или восклицательный знак. Сегодня расставь карточки по заданной модели.':state.view==='creative'?t.plan.join('. '):'Это учебный диалог. Соня задаёт вопросы, а ты говоришь или пишешь свои ответы. Проверь текст после распознавания.';speak(text,true);}
function startListening(){
 if(ensureLesson()){render();return;}
 $$('audio').forEach(a=>a.pause());
 if(state.voice.recording){notify('Сначала заверши запись, затем можно включить распознавание.');render();return;}
 const view=state.view,id=current()?.id,turn=state.turn,epoch=++voiceEpoch;state.voice.listening=true;state.voice.status='Слушаю… Говори спокойно и отчётливо.';render();
 const active=()=>epoch===voiceEpoch&&state.turn===turn&&state.view===view&&current()?.id===id;
 const result=V.listen({onResult:text=>{if(!active())return;changeDraft((state.draft.trim()?state.draft.trim()+' ':'')+text);state.voice.status='Вот что удалось услышать. Проверь текст и при необходимости исправь.';render();},onStatus:text=>{if(!active())return;state.voice.status=text;render();},onError:text=>{if(!active())return;state.voice.status=text;state.voice.listening=false;render();},onEnd:()=>{if(!active())return;state.voice.listening=false;render();}});
 if(!result){state.voice.listening=false;state.voice.status='Распознавание не запустилось. Можно написать ответ или воспользоваться диктовкой клавиатуры.';render();}
}
async function startRecording(){
 if(ensureLesson()){render();return;}
 $$('audio').forEach(a=>a.pause());
 if(state.voice.listening){V.stopListening();state.voice.listening=false;}
 const view=state.view,id=current()?.id,turn=state.turn,epoch=++voiceEpoch;state.voice.recording=true;state.voice.status='Разреши микрофон, чтобы записать голос.';render();
 const active=()=>epoch===voiceEpoch&&state.turn===turn&&state.view===view&&current()?.id===id;
 const ok=await V.startRecording({onStatus:text=>{if(!active())return;state.voice.status=text;render();},onReady:result=>{if(!active())return;state.voice.recording=false;state.voice.url=result.url;state.voice.status='Запись готова. Послушай себя и проверь, понятно ли звучит мысль.';render();},onError:text=>{if(!active())return;state.voice.recording=false;state.voice.status=text;render();}});
 if(!ok&&active()){state.voice.recording=false;render();}
}
function dialogSend(){if(ensureLesson()){render();return;}const t=current(),turn=t.turns[state.turn],text=state.draft.trim();if(K.words(text).length<turn.minWords){notify(`${turn.minWords===1?'Сначала скажи или напиши ответ.':'Попробуй ответить чуть подробнее — полным предложением.'} ${turn.hint}`,'hint');if(text)requireLesson('dialogue');render();return;}resetVoice();state.chat.push({who:'child',text});state.draft='';state.feedback=null;state.turn++;
 if(state.turn>=t.turns.length){state.dialogDone=true;state.chat.push({who:'coach',text:t.wrap});complete();speak(t.wrap);celebrate();}else{const next=t.turns[state.turn],bridge=['Спасибо, я услышала твой ответ.','Теперь давай добавим подробности.','Хорошо, продолжим рассказ.'][Math.min(state.turn-1,2)];state.chat.push({who:'coach',text:bridge+' '+next.prompt});speak(next.prompt);}render();$('.dialog-form,.example-card')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
function celebrate(){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=document.createElement('div');el.className='confetti';el.setAttribute('aria-hidden','true');el.innerHTML=Array.from({length:18},(_,i)=>`<i style="left:${Math.random()*100}%;background:${['#8cb9a1','#ebbb62','#e4a08a','#baa6cf'][i%4]};animation-delay:${Math.random()*.25}s"></i>`).join('');document.body.append(el);setTimeout(()=>el.remove(),2000);}
let lastFocus=null;
function modal(content){if(state.voice.recording||state.voice.listening)resetVoice();lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-btn modal-close" data-action="close-modal" aria-label="Закрыть">${ico('close')}</button>${content}</section></div>`;$('.modal-close').focus();}
function closeModal(){$('#overlay').innerHTML='';lastFocus?.focus();}
function help(){const caps=V.capabilities();modal(`<span class="guide-icon">${ico('book')}</span><h2 id="modal-title">Добро пожаловать в Словоград</h2><p>Выбери 1-й или 2-й класс наверху. В «Секретах слова» все части доступны в обоих классах. В других разделах можно выбрать конкретную тему для более сложных заданий. Они отмечены «Шаг сложнее».</p><ol><li><b>Сначала разберись.</b> Перед новой темой прочитай или послушай правило со схемами и нажми «Понял — к заданию».</li><li><b>Попробуй сам.</b> Собирай карточки, выделяй части слова, пиши и сочиняй.</li><li><b>Ошибка подскажет, что повторить.</b> Откроется нужное правило. После чтения вернёшься к тому же заданию: твой ответ останется на месте. Подробности доступны и по кнопке рядом с правилом.</li><li><b>Закрепи.</b> Задания, которые вызвали трудности, доступны в «Моих открытиях».</li></ol><h3>Как закрепляем правило</h3><p>В Буквенной мастерской сначала собираем слова, затем пишем другие слова сами, потом выполняем диктант. Следующее правило начинается после трёх шагов. Место, незаконченный ответ и отметки сохраняются отдельно для каждого класса и режима. При повторном открытии занятие продолжается с того же места. Для отдельного упражнения есть свободная практика.</p><p>В 1-м классе основной маршрут содержит 120 слов, во 2-м — 240. Во втором классе больше сложных слов, а базовые правила повторяются. Другие разделы тоже учитывают класс. В свободной практике 1-го класса можно отдельно включить задания 2-го класса.</p><h3>Про голос</h3><p>Правила, слова и задания читает один женский голос. Для аудиозаписей нужен интернет. Свои предложения и ответы ребёнка читает голос устройства: его звучание и ударения зависят от браузера и ОС.</p><p>Озвучка ${caps.tts?'доступна':'недоступна'}; распознавание ${caps.recognition?'поддерживается браузером, но может зависеть от его настроек и сети':'недоступно — используй ввод с клавиатуры или её диктовку'}; запись голоса ${caps.recording?'доступна после разрешения микрофона':'недоступна в этом браузере'}.</p><p>Распознанный текст — черновик, а не оценка произношения. Запись для прослушивания хранится только на устройстве. Распознавание может использовать службу браузера или ОС. Микрофон включается только по нажатию.</p><p>Разговоры с Соней идут по учебному сценарию. Задания на красивую речь помогают сочинять по плану; автоматическая проверка не заменяет проверку смысла и всей грамматики.</p><p class="task-note muted"><a href="voice-credits.txt" target="_blank" rel="noopener">Об аудиозаписях и лицензии</a></p><p class="muted">Прогресс хранится в этом браузере. Математические тренажёры остаются отдельными сайтами.</p><button class="btn primary" data-action="download">Скачать для занятий без интернета</button><p class="task-note muted">Без интернета работают задания. Для записанного женского голоса нужен интернет. Распознавание зависит от браузера и его сетевой службы.</p>`);}
async function download(){const button=$('[data-action="download"]');if(location.protocol==='file:'||location.protocol==='content:'){button.textContent='Это уже автономная версия';return;}button.disabled=true;try{const names=['style.css','lessons.css','words.js','sentences.js','creative.js','illustrations.js','core.js','voice-manifest.js','recorded-voice.js','voice.js','lessons.js','app.js'];const files=await Promise.all(names.map(name=>fetch(name,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('fetch');return r.text();})));const head=document.head.innerHTML.replace(/<(?:link|meta)\b(?=[^>]*\bdata-pwa\b)[^>]*>/gi,'').replace(/<link rel="stylesheet" href="style\.css(?:\?[^"]*)?">/,()=>`<style>${files[0]}</style>`).replace(/<link rel="stylesheet" href="lessons\.css(?:\?[^"]*)?">/,()=>`<style>${files[1]}</style>`),scripts=files.slice(2).map(s=>'<script>'+s.replace(/<\/script/gi,'<\\/script')+'</script>').join('');const audioBase='<script>window.VOICE_AUDIO_BASE='+JSON.stringify(new URL('./',location.href).href)+';</script>';const html='<!doctype html><html lang="ru"><head>'+head+'</head><body><div id="app"></div><div id="overlay"></div><div id="live" class="sr-only" aria-live="polite"></div>'+audioBase+scripts+'</body></html>';const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='slovograd-russkiy.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);button.textContent='Скачано — задания без интернета, аудио с интернетом';}catch{button.disabled=false;button.textContent='Не удалось скачать. Попробовать снова';}}
function changeDraft(text){if(state.lesson)return;state.draft=text.slice(0,1800);if(state.solved&&state.view==='creative'){const id=document.activeElement?.id,pos=document.activeElement?.selectionStart;state.solved=false;state.feedback=null;render();if(id&&$('#'+id)&&typeof pos==='number')$('#'+id).setSelectionRange?.(pos,pos);}rememberSession();}
