let drag=null;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-drag]');if(!el||el.disabled||state.solved||state.lesson||e.button!==0)return;drag={id:e.pointerId,type:el.dataset.drag,item:+el.dataset.id,x:e.clientX,y:e.clientY,el,active:false};el.setPointerCapture?.(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;if(!drag.active&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7){drag.active=true;drag.ghost=drag.el.cloneNode(true);drag.ghost.removeAttribute('data-drag');drag.ghost.classList.add('drag-ghost');drag.ghost.setAttribute('aria-hidden','true');document.body.append(drag.ghost);}if(drag.active){e.preventDefault();drag.ghost.style.left=e.clientX+'px';drag.ghost.style.top=e.clientY+'px';$$('.drop-over').forEach(x=>x.classList.remove('drop-over'));document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]')?.classList.add('drop-over');}},{passive:false});
function finishDrag(e,cancel=false){if(!drag||drag.id!==e.pointerId)return;const d=drag;drag=null;d.ghost?.remove();$$('.drop-over').forEach(x=>x.classList.remove('drop-over'));if(!d.active)return;suppressClick=true;setTimeout(()=>{suppressClick=false;},100);if(cancel||state.lesson)return;const target=document.elementFromPoint(e.clientX,e.clientY),area=target?.closest('[data-drop]');if(!area)return;let ids=[...state.assembled];if(area.dataset.drop==='bank'){if(d.type==='assembled')ids=ids.filter(id=>id!==d.item);}else if(area.dataset.drop==='word'||area.dataset.drop==='sentence'){if(!ids.includes(d.item)&&area.dataset.drop==='word'&&ids.length>=current().word.length)return;ids=ids.filter(id=>id!==d.item);const position=Number(target.closest('[data-slot]')?.dataset.slot??ids.length);ids.splice(Math.min(position,ids.length),0,d.item);}state.assembled=ids;state.feedback=null;render();}
document.addEventListener('pointerup',e=>finishDrag(e));document.addEventListener('pointercancel',e=>finishDrag(e,true));
restoreApplication();resumeReady=true;render();
